package app.typeandframe.studio.collagefilters

class TriangleFilter :
    BaseGlitchGPUImageFilter("uniform mat4 uMVPMatrix;attribute vec4 position;\nattribute vec4 inputTextureCoordinate;\n \nvarying vec2 textureCoordinate;\n \nvoid main()\n{\n    gl_Position = uMVPMatrix * position;\n    textureCoordinate = inputTextureCoordinate.xy;\n}", "precision highp float;\nvarying highp vec2 textureCoordinate;\nuniform sampler2D inputImageTexture;\nuniform highp vec2 inputSize;\nuniform highp float iTime;\n\nvoid main()\n{\n    float cell_size = (iTime + 15.0)/1000.0;\n\n    vec2 xy;\n    xy.x = textureCoordinate[0];\n    xy.y = textureCoordinate[1];\n\n\n    float CellWidth = cell_size;\n    float CellHeight = cell_size;\n\n    CellHeight = cell_size * inputSize.x / inputSize.y;\n\n    float x1 = floor(xy.x / CellWidth)*CellWidth;\n    float x2 = clamp((ceil(xy.x / CellWidth)*CellWidth), 0.0, 1.0);\n    float y1 = floor(xy.y / CellHeight)*CellHeight;\n    float y2 = clamp((ceil(xy.y / CellHeight)*CellHeight), 0.0, 1.0);\n\n    float x = (xy.x-x1) / CellWidth;\n    float y = (xy.y-y1) / CellHeight;\n    vec4 avgClr = vec4(0.0);\n\n    if ((x > y)&&(x < 1.0 - y))    {\n        vec4 avgL = texture2D(inputImageTexture, vec2(x1, y1));\n        vec4 avgR = texture2D(inputImageTexture, vec2(x2, y1));\n        vec4 avgC = texture2D(inputImageTexture, vec2(x1+(CellWidth/2.0), y2+(CellHeight/2.0)));\n        avgClr = (avgL+avgR+avgC) / 3.0;\n    }\n    else if ((x < y)&&(x < 1.0 - y))    {\n        vec4 avgL = texture2D(inputImageTexture, vec2(x1, y1));\n        vec4 avgR = texture2D(inputImageTexture, vec2(x1, y2));\n        vec4 avgC = texture2D(inputImageTexture, vec2(x1+(CellWidth/2.0), y2+(CellHeight/2.0)));\n        avgClr = (avgL+avgR+avgC) / 3.0;\n    }\n    else if ((x > 1.0 - y)&&(x < y))    {\n        vec4 avgL = texture2D(inputImageTexture, vec2(x1, y2));\n        vec4 avgR = texture2D(inputImageTexture, vec2(x2, y2));\n        vec4 avgC = texture2D(inputImageTexture, vec2(x1+(CellWidth/2.0), y2+(CellHeight/2.0)));\n        avgClr = (avgL+avgR+avgC) / 3.0;\n    }\n    else    {\n        vec4 avgL = texture2D(inputImageTexture, vec2(x2, y1));\n        vec4 avgR = texture2D(inputImageTexture, vec2(x2, y2));\n        vec4 avgC = texture2D(inputImageTexture, vec2(x1+(CellWidth/2.0), y2+(CellHeight/2.0)));\n        avgClr = (avgL+avgR+avgC) / 3.0;\n    }\n\n    gl_FragColor = avgClr;\n}"), AdjustableFilter {
    override fun setAmount(amountValue: Float) {
        setTime(amountValue)
    }
}
